'use strict';

// MODULES //

var hingeGradient = require( '@stdlib/ml/base/loss/float64/hinge-gradient' );
var logGradient = require( '@stdlib/ml/base/loss/float64/log-gradient' );
var modifiedHuberGradient = require( '@stdlib/ml/base/loss/float64/modified-huber-gradient' );
var squaredHingeGradient = require( '@stdlib/ml/base/loss/float64/squared-hinge-gradient' );
var squaredErrorGradient = require( '@stdlib/ml/base/loss/float64/squared-error-gradient' );
var huberGradient = require( '@stdlib/ml/base/loss/float64/huber-gradient' );
var epsilonInsensitiveGradient = require( '@stdlib/ml/base/loss/float64/epsilon-insensitive-gradient' );
var squaredEpsilonInsensitiveGradient = require( '@stdlib/ml/base/loss/float64/squared-epsilon-insensitive-gradient' );


// VARIABLES //

var LOSS_FUNCTIONS = {
	'epsilon-insensitive': epsilonInsensitive,
	'hinge': hinge,
	'huber': huber,
	'log': log,
	'modified-huber': modifiedHuber,
	'perceptron': perceptron,
	'squared-error': squaredError,
	'squared-epsilon-insensitive': squaredEpsilonInsensitive,
	'squared-hinge': squaredHinge
};


// FUNCTIONS //

// params => [ ]
function hinge( y, p, params ) {
	hingeGradient( 1.0, 1.0, y, p );
}

// params => [ ]
function perceptron( y, p, params ) {
	hingeGradient( 1.0, 0.0, y, p );
}

// params => [ ]
function log( y, p, params ) {
	logGradient( 1.0, y, p );
}

function squaredHinge( y, p, params ) {
	squaredHingeGradient( 1.0, y, p );
}

function modifiedHuber( y, p, params ) {
	modifiedHuberGradient( 1.0, y, p );
}

function squaredError( y, p, params ) {
	squaredErrorGradient( 1.0, y, p );
}

function huber( y, p, params ) {
	huberGradient( 1.0, y, p );
}

function epsilonInsensitive( y, p, params ) {
	epsilonInsensitiveGradient( 1.0, params[ 0 ], y, p );
}

function squaredEpsilonInsensitive( y, p, params ) {
	squaredEpsilonInsensitiveGradient( 1.0, params[ 0 ], y, p );
}

// MAIN //


